import { getScopedNavForPath } from './scopeNavToPath.js';
import { DivisionMatchLevel, updateFirstHrefInDivision, } from './updateFirstHrefInDivision.js';
const emptyDivisions = {
    tabs: [],
    anchors: [],
    versions: [],
    languages: [],
    dropdowns: [],
    products: [],
    menu: [],
};
function visit(firstHrefInDivision, href, nearestDivisionValue) {
    const page = { title: href, href };
    updateFirstHrefInDivision({
        type: 'version',
        currentPath: '/docs',
        entry: page,
        parentGroups: [],
        nearestDivisionValue,
        isActiveGroup: false,
        inActiveDivision: false,
        currentDivisionValue: undefined,
        allDivisionValues: ['v2', 'v1'],
        firstHrefInDivision,
        navigationDivisions: emptyDivisions,
        isHiddenPage: false,
    });
}
describe(updateFirstHrefInDivision, () => {
    it('prefers a division-owned page over an earlier unversioned catch-all', () => {
        const map = new Map();
        visit(map, '/docs/getting-started', undefined);
        visit(map, '/docs/v1/overview', 'v1');
        expect(map.get('v1')).toEqual({
            href: '/docs/v1/overview',
            matchLevel: DivisionMatchLevel.NONE,
        });
        expect(map.get('v2')).toEqual({
            href: '/docs/getting-started',
            matchLevel: DivisionMatchLevel.UNVERSIONED,
        });
    });
    it('keeps the first division-owned page regardless of visit order', () => {
        const map = new Map();
        visit(map, '/docs/v1/overview', 'v1');
        visit(map, '/docs/getting-started', undefined);
        visit(map, '/docs/v1/later-page', 'v1');
        expect(map.get('v1')).toEqual({
            href: '/docs/v1/overview',
            matchLevel: DivisionMatchLevel.NONE,
        });
    });
});
describe('language translation matches', () => {
    const page = (href, extra = {}) => (Object.assign({ title: href, href }, extra));
    const nav = {
        languages: [
            {
                language: 'en',
                default: true,
                pages: [
                    page('/visible'),
                    page('/hidden-page'),
                    page('/in-hidden-group'),
                    page('/gated'),
                    page('/noindexed'),
                ],
            },
            {
                language: 'es',
                groups: [
                    {
                        group: 'Visible',
                        pages: [
                            page('/es/visible'),
                            page('/es/hidden-page', { hidden: true }),
                            page('/es/gated', { groups: ['staff'] }),
                            page('/es/noindexed', { noindex: true }),
                        ],
                    },
                    { group: 'Hidden', hidden: true, pages: [page('/es/in-hidden-group')] },
                ],
            },
        ],
    };
    const esMatch = (currentPath) => getScopedNavForPath({ decoratedNav: nav, currentPath }).firstHrefInLanguage.get('es');
    it('records the translated page visibility on path matches', () => {
        expect(esMatch('/visible')).toEqual({
            href: '/es/visible',
            matchLevel: DivisionMatchLevel.PATH,
        });
        expect(esMatch('/hidden-page')).toEqual({
            href: '/es/hidden-page',
            matchLevel: DivisionMatchLevel.PATH,
            hidden: true,
        });
        expect(esMatch('/in-hidden-group')).toEqual({
            href: '/es/in-hidden-group',
            matchLevel: DivisionMatchLevel.PATH,
            hidden: true,
        });
        expect(esMatch('/noindexed')).toEqual({
            href: '/es/noindexed',
            matchLevel: DivisionMatchLevel.PATH,
            noindex: true,
        });
        expect(esMatch('/gated')).toEqual({
            href: '/es/gated',
            matchLevel: DivisionMatchLevel.PATH,
            groups: ['staff'],
        });
    });
});
